/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'fs'

const args = process.argv.slice(2)

// ============================================================================
// Argument Parsing
// ============================================================================

let mode = null
let workerCount = null

if (args.length === 0 || args.length > 2) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

if (args[0] === 'waves') {
  mode = 'waves'
} else if (args[0] === 'explain') {
  mode = 'explain'
} else if (args[0] === 'pack') {
  if (args.length !== 2) {
    process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
    process.exit(2)
  }
  mode = 'pack'
  const workerArg = args[1]

  // Validate worker count: must be positive integer without sign or leading zero
  if (!/^[1-9]\d*$/.test(workerArg)) {
    process.stderr.write('error: workers must be a positive integer\n')
    process.exit(2)
  }
  workerCount = parseInt(workerArg, 10)
} else {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

// ============================================================================
// Input Parsing
// ============================================================================

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')

// Remove trailing empty line if present
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

const tasks = new Map() // name -> cost
const dependencies = new Map() // name -> Set of dependency names
let maxLineNum = 0

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
  let line = lines[lineNum].trim()

  // Ignore empty lines and comments
  if (line === '' || line.startsWith('#')) {
    continue
  }

  maxLineNum = lineNum + 1

  // Split on runs of whitespace
  const parts = line.split(/\s+/)

  if (parts.length === 0) {
    continue
  }

  const directive = parts[0]

  if (directive === 'task') {
    if (parts.length !== 3) {
      process.stderr.write(`error: line ${lineNum + 1}: expected task <name> <cost>\n`)
      process.exit(2)
    }

    const name = parts[1]
    const costStr = parts[2]

    // Validate task name
    if (!/^[A-Za-z0-9_.-]+$/.test(name)) {
      process.stderr.write(`error: line ${lineNum + 1}: invalid task name ${name}\n`)
      process.exit(2)
    }

    // Validate cost
    if (!/^\d+$/.test(costStr)) {
      process.stderr.write(`error: line ${lineNum + 1}: cost must be a non-negative integer\n`)
      process.exit(2)
    }

    const cost = parseInt(costStr, 10)

    // Check for duplicate
    if (tasks.has(name)) {
      process.stderr.write(`error: line ${lineNum + 1}: task ${name} is declared twice\n`)
      process.exit(2)
    }

    tasks.set(name, cost)
    if (!dependencies.has(name)) {
      dependencies.set(name, new Set())
    }
  } else if (directive === 'dep') {
    if (parts.length < 2) {
      process.stderr.write(`error: line ${lineNum + 1}: expected dep <name> <dependency>...\n`)
      process.exit(2)
    }

    const name = parts[0]
    const deps = parts.slice(1)

    // Initialize if not seen
    if (!dependencies.has(name)) {
      dependencies.set(name, new Set())
    }

    // Add dependencies
    for (const dep of deps) {
      dependencies.get(name).add(dep)
    }
  } else {
    process.stderr.write(`error: line ${lineNum + 1}: unknown directive ${directive}\n`)
    process.exit(2)
  }
}

// ============================================================================
// Validation
// ============================================================================

// Check that all dependencies refer to declared tasks
for (const [name, deps] of dependencies) {
  for (const dep of deps) {
    if (!tasks.has(dep)) {
      process.stderr.write(`error: unknown task ${dep}\n`)
      process.exit(2)
    }
  }
}

// ============================================================================
// Cycle Detection
// ============================================================================

function detectCycle() {
  const visited = new Set()
  const recStack = new Set()
  const stack = [] // For tracking the path

  function dfs(node) {
    visited.add(node)
    recStack.add(node)
    stack.push(node)

    const deps = dependencies.get(node) || new Set()
    const sortedDeps = Array.from(deps).sort()

    for (const dep of sortedDeps) {
      if (!visited.has(dep)) {
        if (dfs(dep)) {
          return true
        }
      } else if (recStack.has(dep)) {
        // Found a cycle
        const cycleStart = stack.indexOf(dep)
        const cycle = stack.slice(cycleStart)
        cycle.push(dep)
        process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
        process.exit(3)
      }
    }

    stack.pop()
    recStack.delete(node)
    return false
  }

  const taskNames = Array.from(tasks.keys()).sort()
  for (const name of taskNames) {
    if (!visited.has(name)) {
      dfs(name)
    }
  }
}

detectCycle()

// ============================================================================
// Calculate depths (waves)
// ============================================================================

function calculateDepths() {
  const depths = new Map() // name -> depth
  const visited = new Set()

  function getDepth(name) {
    if (depths.has(name)) {
      return depths.get(name)
    }

    const deps = dependencies.get(name) || new Set()
    if (deps.size === 0) {
      depths.set(name, 0)
      return 0
    }

    let maxDepth = -1
    for (const dep of deps) {
      const depDepth = getDepth(dep)
      maxDepth = Math.max(maxDepth, depDepth)
    }

    const depth = maxDepth + 1
    depths.set(name, depth)
    return depth
  }

  for (const name of tasks.keys()) {
    getDepth(name)
  }

  return depths
}

const depths = calculateDepths()

// ============================================================================
// Calculate start/finish times
// ============================================================================

function calculateTimes() {
  const times = new Map() // name -> { start, finish }

  function getTime(name) {
    if (times.has(name)) {
      return times.get(name)
    }

    const deps = dependencies.get(name) || new Set()
    let start = 0

    for (const dep of deps) {
      const depTime = getTime(dep)
      start = Math.max(start, depTime.finish)
    }

    const cost = tasks.get(name)
    const finish = start + cost

    times.set(name, { start, finish })
    return { start, finish }
  }

  for (const name of tasks.keys()) {
    getTime(name)
  }

  return times
}

const times = calculateTimes()

// ============================================================================
// Calculate priorities (longest chain from each task)
// ============================================================================

function calculatePriorities() {
  const priorities = new Map() // name -> priority (cost of longest chain)

  function getPriority(name) {
    if (priorities.has(name)) {
      return priorities.get(name)
    }

    const cost = tasks.get(name)

    // Find all tasks that depend on this task (reverse dependencies)
    let maxChain = cost

    for (const [taskName, taskDeps] of dependencies) {
      if (taskDeps.has(name)) {
        const chainFromDependent = getPriority(taskName)
        maxChain = Math.max(maxChain, cost + chainFromDependent)
      }
    }

    priorities.set(name, maxChain)
    return maxChain
  }

  for (const name of tasks.keys()) {
    getPriority(name)
  }

  return priorities
}

const priorities = calculatePriorities()

// ============================================================================
// Commands
// ============================================================================

if (mode === 'waves') {
  const waveMap = new Map()

  for (const [name, depth] of depths) {
    if (!waveMap.has(depth)) {
      waveMap.set(depth, [])
    }
    waveMap.get(depth).push(name)
  }

  // Sort tasks within each wave
  for (const wave of waveMap.values()) {
    wave.sort()
  }

  // Output waves in order
  const maxWave = Math.max(...Array.from(depths.values()), -1)
  for (let w = 0; w <= maxWave; w++) {
    if (waveMap.has(w)) {
      const taskList = waveMap.get(w)
      process.stdout.write(`wave ${w}: ${taskList.join(' ')}\n`)
    }
  }

  // Calculate total makespan
  let totalMakespan = 0
  for (const time of times.values()) {
    totalMakespan = Math.max(totalMakespan, time.finish)
  }

  process.stdout.write(`total ${totalMakespan}\n`)
} else if (mode === 'explain') {
  const taskNames = Array.from(tasks.keys()).sort()

  for (const name of taskNames) {
    const time = times.get(name)
    const depth = depths.get(name)
    process.stdout.write(`${name} start=${time.start} finish=${time.finish} depth=${depth}\n`)
  }

  // Calculate total makespan
  let totalMakespan = 0
  for (const time of times.values()) {
    totalMakespan = Math.max(totalMakespan, time.finish)
  }

  process.stdout.write(`total ${totalMakespan}\n`)
} else if (mode === 'pack') {
  // Simulate scheduling on N workers
  const workers = Array.from({ length: workerCount }, () => ({
    free_at: 0,
    tasks: []
  }))

  // Track which tasks have finished
  const finished = new Set()

  // Track when each task finishes
  const finishTimes = new Map()

  // Priority queue simulation - process time steps
  let currentTime = 0

  while (finished.size < tasks.size) {
    // Find all ready tasks (all dependencies finished)
    const ready = []

    for (const [name, deps] of dependencies) {
      if (finished.has(name)) continue

      let allDepsFinished = true
      for (const dep of deps) {
        if (!finished.has(dep)) {
          allDepsFinished = false
          break
        }
      }

      if (allDepsFinished) {
        ready.push(name)
      }
    }

    // Sort ready tasks by priority (descending) then by name (ascending)
    ready.sort((a, b) => {
      const priorityDiff = priorities.get(b) - priorities.get(a)
      if (priorityDiff !== 0) return priorityDiff
      return a.localeCompare(b)
    })

    // Assign ready tasks to free workers
    let assigned = false

    for (const taskName of ready) {
      // Find the first free worker at currentTime
      let bestWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (workers[i].free_at <= currentTime) {
          bestWorker = i
          break
        }
      }

      if (bestWorker !== -1) {
        const cost = tasks.get(taskName)
        const start = currentTime
        const finish = start + cost

        workers[bestWorker].tasks.push({ name: taskName, start, finish })
        workers[bestWorker].free_at = finish
        finished.add(taskName)
        finishTimes.set(taskName, finish)
        assigned = true
      } else {
        break
      }
    }

    if (!assigned && finished.size < tasks.size) {
      // No tasks were assigned, advance time to next worker free time
      currentTime = Math.min(...workers.map(w => w.free_at))
    } else if (assigned) {
      // Try to assign more at the current time
      // We need to continue the loop to try assigning more tasks
    } else {
      break
    }
  }

  // Output results
  let maxFinish = 0
  for (let i = 0; i < workerCount; i++) {
    const worker = workers[i]
    let line = `worker ${i}:`

    for (const task of worker.tasks) {
      line += ` ${task.name}@${task.start}-${task.finish}`
      maxFinish = Math.max(maxFinish, task.finish)
    }

    process.stdout.write(line + '\n')
  }

  process.stdout.write(`makespan ${maxFinish}\n`)
}
