{"file_path":"src/parse.js","content":"const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Reads the build graph from the text of standard input.
 * Returns { names, cost, deps } where deps maps a name to a Set of names.
 */
export function parseGraph(text, fail) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const names = []
  const cost = new Map()
  const deps = new Map()
  const used = [] // names a dep line mentions, in input order

  const ensure = (name) => {
    if (!deps.has(name)) deps.set(name, new Set())
  }

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`, 2)
      const name = words[1]
      if (!NAME.test(name)) fail(`error: line ${n}: invalid task name ${name}`, 2)
      if (!COST.test(words[2])) fail(`error: line ${n}: cost must be a non-negative integer`, 2)
      if (cost.has(name)) fail(`error: line ${n}: task ${name} is declared twice`, 2)
      cost.set(name, Number(words[2]))
      names.push(name)
      ensure(name)
    } else if (directive === 'dep') {
      if (words.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`, 2)
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) fail(`error: line ${n}: invalid task name ${words[w]}`, 2)
      }
      const target = words[1]
      used.push(target)
      ensure(target)
      for (let w = 2; w < words.length; w++) {
        used.push(words[w])
        deps.get(target).add(words[w])
      }
    } else {
      fail(`error: line ${n}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of used) {
    if (!cost.has(name)) fail(`error: unknown task ${name}`, 2)
  }

  return { names, cost, deps }
}
"}

