{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { parseGraph } from './parse.js'
import { analyse } from './graph.js'
import { pack } from './pack.js'

function fail(message, code) {
  process.stderr.write(message + '\n')
  process.exit(code)
}

const argv = process.argv.slice(2)
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

let mode = null
let workers = 0

if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
  mode = argv[0]
} else if (argv.length === 2 && argv[0] === 'pack') {
  mode = 'pack'
  if (!/^[1-9][0-9]*$/.test(argv[1])) fail('error: workers must be a positive integer', 2)
  workers = Number(argv[1])
} else {
  fail(USAGE, 2)
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const graph = parseGraph(input, fail)
const info = analyse(graph, fail)

const out = []

if (mode === 'waves') {
  const waves = []
  for (const name of graph.names) {
    const d = info.depth.get(name)
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }
  for (let i = 0; i < waves.length; i++) {
    const list = (waves[i] || []).slice().sort(byName)
    out.push(`wave ${i}: ${list.join(' ')}`)
  }
  out.push(`total ${info.total}`)
} else if (mode === 'explain') {
  for (const name of graph.names.slice().sort(byName)) {
    out.push(`${name} start=${info.start.get(name)} finish=${info.finish.get(name)} depth=${info.depth.get(name)}`)
  }
  out.push(`total ${info.total}`)
} else {
  const result = pack(graph, info, workers)
  for (let i = 0; i < workers; i++) {
    let line = `worker ${i}:`
    for (const run of result.lanes[i]) line += ` ${run.name}@${run.start}-${run.finish}`
    out.push(line)
  }
  out.push(`makespan ${result.makespan}`)
}

function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

{"file_path":"src/parse.js","content":"const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Reads the build graph from the text of standard input.
 * Returns { names, cost, deps } where deps maps a name to a Set of names.
 */
export function parseGraph(text, fail) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const names = []
  const cost = new Map()
  const deps = new Map()
  const used = [] // names a dep line mentions, in input order

  const ensure = (name) => {
    if (!deps.has(name)) deps.set(name, new Set())
  }

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`, 2)
      const name = words[1]
      if (!NAME.test(name)) fail(`error: line ${n}: invalid task name ${name}`, 2)
      if (!COST.test(words[2])) fail(`error: line ${n}: cost must be a non-negative integer`, 2)
      if (cost.has(name)) fail(`error: line ${n}: task ${name} is declared twice`, 2)
      cost.set(name, Number(words[2]))
      names.push(name)
      ensure(name)
    } else if (directive === 'dep') {
      if (words.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`, 2)
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) fail(`error: line ${n}: invalid task name ${words[w]}`, 2)
      }
      const target = words[1]
      used.push(target)
      ensure(target)
      for (let w = 2; w < words.length; w++) {
        used.push(words[w])
        deps.get(target).add(words[w])
      }
    } else {
      fail(`error: line ${n}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of used) {
    if (!cost.has(name)) fail(`error: unknown task ${name}`, 2)
  }

  return { names, cost, deps }
}
"}

