/**
 * Rejects a cycle, then reports the depth, start, finish and priority of
 * every task along with the unlimited-worker makespan.
 */
export function analyse(graph, fail) {
  const { names, cost, deps } = graph
  const sorted = names.slice().sort(byName)

  const sortedDeps = new Map()
  for (const name of names) sortedDeps.set(name, Array.from(deps.get(name) || []).sort(byName))

  detectCycle(sorted, sortedDeps, fail)

  const order = topoOrder(sorted, sortedDeps)

  const depth = new Map()
  const start = new Map()
  const finish = new Map()
  let total = 0
  for (const name of order) {
    let d = 0
    let s = 0
    for (const dep of sortedDeps.get(name)) {
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    depth.set(name, d)
    start.set(name, s)
    const f = s + cost.get(name)
    finish.set(name, f)
    if (f > total) total = f
  }

  // priority: cost of the longest chain that begins at the task
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const name of names) {
    for (const dep of sortedDeps.get(name)) dependents.get(dep).push(name)
  }
  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let best = 0
    for (const child of dependents.get(name)) best = Math.max(best, priority.get(child))
    priority.set(name, cost.get(name) + best)
  }

  return { depth, start, finish, priority, total }
}

function detectCycle(sorted, sortedDeps, fail) {
  const colour = new Map() // 1 = on the stack, 2 = done
  for (const root of sorted) {
    if (colour.get(root)) continue
    const path = [root]
    const stack = [{ node: root, i: 0 }]
    colour.set(root, 1)
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const list = sortedDeps.get(frame.node)
      if (frame.i < list.length) {
        const next = list[frame.i++]
        const c = colour.get(next) || 0
        if (c === 1) {
          const cycle = path.slice(path.indexOf(next))
          cycle.push(next)
          fail(`error: cycle: ${cycle.join(' -> ')}`, 3)
        } else if (c === 0) {
          colour.set(next, 1)
          path.push(next)
          stack.push({ node: next, i: 0 })
        }
      } else {
        colour.set(frame.node, 2)
        stack.pop()
        path.pop()
      }
    }
  }
}

function topoOrder(sorted, sortedDeps) {
  const done = new Set()
  const order = []
  for (const root of sorted) {
    if (done.has(root)) continue
    const stack = [{ node: root, i: 0 }]
    done.add(root)
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const list = sortedDeps.get(frame.node)
      if (frame.i < list.length) {
        const next = list[frame.i++]
        if (!done.has(next)) {
          done.add(next)
          stack.push({ node: next, i: 0 })
        }
      } else {
        order.push(frame.node)
        stack.pop()
      }
    }
  }
  return order
}
