/** Simulates the graph on a fixed number of workers. */
export function pack(graph, info, workerCount) {
  const { names, cost, deps } = graph
  const lanes = []
  const free = []
  for (let i = 0; i < workerCount; i++) {
    lanes.push([])
    free.push(0)
  }

  const pending = names.slice().sort(byName)
  const done = new Map() // name -> finish time
  let time = 0
  let makespan = 0

  while (done.size < pending.length) {
    let started = false
    for (;;) {
      let worker = -1
      for (let i = 0; i < workerCount; i++) {
        if (free[i] <= time) {
          worker = i
          break
        }
      }
      if (worker === -1) break

      let choice = null
      for (const name of pending) {
        if (done.has(name)) continue
        let ready = true
        for (const dep of deps.get(name) || []) {
          const f = done.get(dep)
          if (f === undefined || f > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (choice === null || info.priority.get(name) > info.priority.get(choice)) choice = name
      }
      if (choice === null) break

      const start = time
      const finish = start + cost.get(choice)
      lanes[worker].push({ name: choice, start, finish })
      free[worker] = finish
      done.set(choice, finish)
      if (finish > makespan) makespan = finish
      started = true
    }

    if (done.size >= pending.length) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (free[i] > time && free[i] < next) next = free[i]
    }
    if (next === Infinity) {
      if (!started) break
      continue
    }
    time = next
  }

  return { lanes, makespan }
}
